-- ==================== TIMER SYNC FUNCTIONS ====================

local function findGameTimer()
    -- Method 1: Search in PlayerGui
    for _, gui in pairs(LocalPlayer.PlayerGui:GetDescendants()) do
        if gui:IsA("TextLabel") then
            local text = gui.Text
            if text and (text:match("TIME:") or text:match("%d+:%d+")) then
                return gui
            end
        end
    end
    
    -- Method 2: Search in Workspace for timer values
    for _, obj in pairs(workspace:GetDescendants()) do
        if obj:IsA("IntValue") or obj:IsA("NumberValue") then
            if obj.Name:lower():find("time") or obj.Name:lower():find("hour") or obj.Name:lower():find("minute") then
                return obj
            end
        end
    end
    
    -- Method 3: Search for StringValue with time
    for _, obj in pairs(workspace:GetDescendants()) do
        if obj:IsA("StringValue") then
            if obj.Value and obj.Value:match("%d+:%d+") then
                return obj
            end
        end
    end
    
    return nil
end

local function parseTimeFromText(text)
    local hour, minute = text:match("(%d+):(%d+)")
    if hour and minute then
        return tonumber(hour), tonumber(minute)
    end
    return nil, nil
end

local function getGameTime()
    if not GameTimerValue or not GameTimerValue.Parent then
        GameTimerValue = findGameTimer()
    end
    
    if GameTimerValue then
        if GameTimerValue:IsA("TextLabel") then
            local hour, minute = parseTimeFromText(GameTimerValue.Text)
            if hour and minute then
                return hour, minute
            end
        elseif GameTimerValue:IsA("IntValue") or GameTimerValue:IsA("NumberValue") then
            local totalMinutes = math.floor(GameTimerValue.Value / 60)
            local hour = (totalMinutes % 12)
            if hour == 0 then hour = 12 end
            local minute = totalMinutes % 60
            return hour, minute
        elseif GameTimerValue:IsA("StringValue") then
            local hour, minute = parseTimeFromText(GameTimerValue.Value)
            if hour and minute then
                return hour, minute
            end
        end
    end
    
    return nil, nil
end

-- ==================== DRAGGABLE TIMER GUI ====================

local function makeDraggable(frame)
    local function update(input)
        local delta = input.Position - mousePos
        frame.Position = UDim2.new(
            framePos.X.Scale,
            framePos.X.Offset + delta.X,
            framePos.Y.Scale,
            framePos.Y.Offset + delta.Y
        )
    end

    frame.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            dragging = true
            mousePos = input.Position
            framePos = frame.Position

            input.Changed:Connect(function()
                if input.UserInputState == Enum.UserInputState.End then
                    dragging = false
                end
            end)
        end
    end)

    frame.InputChanged:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
            dragInput = input
        end
    end)

    UserInputService.InputChanged:Connect(function(input)
        if input == dragInput and dragging then
            update(input)
        end
    end)
end

local function createTimerGui()
    if TimerGui then TimerGui:Destroy() end
    
    TimerGui = Instance.new("ScreenGui")
    TimerGui.Name = "EternalNightsTimer"
    TimerGui.ResetOnSpawn = false
    TimerGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    TimerGui.Parent = LocalPlayer.PlayerGui
    
    local mainFrame = Instance.new("Frame")
    mainFrame.Name = "MainFrame"
    mainFrame.Size = UDim2.new(0, 280, 0, 100)
    mainFrame.Position = UDim2.new(0.5, -140, 0, 50)
    mainFrame.BackgroundColor3 = Color3.fromRGB(20, 20, 25)
    mainFrame.BorderSizePixel = 0
    mainFrame.Active = true
    mainFrame.Parent = TimerGui
    
    local corner = Instance.new("UICorner")
    corner.CornerRadius = UDim.new(0, 15)
    corner.Parent = mainFrame
    
    local gradient = Instance.new("UIGradient")
    gradient.Color = ColorSequence.new{
        ColorSequenceKeypoint.new(0, Color3.fromRGB(30, 30, 40)),
        ColorSequenceKeypoint.new(1, Color3.fromRGB(15, 15, 20))
    }
    gradient.Rotation = 45
    gradient.Parent = mainFrame
    
    local stroke = Instance.new("UIStroke")
    stroke.Color = Color3.fromRGB(100, 150, 255)
    stroke.Thickness = 2.5
    stroke.Transparency = 0.3
    stroke.Parent = mainFrame
    
    local titleLabel = Instance.new("TextLabel")
    titleLabel.Name = "TitleLabel"
    titleLabel.Size = UDim2.new(1, 0, 0, 30)
    titleLabel.Position = UDim2.new(0, 0, 0, 8)
    titleLabel.BackgroundTransparency = 1
    titleLabel.Text = "NIGHT TIME"
    titleLabel.TextColor3 = Color3.fromRGB(150, 180, 255)
    titleLabel.TextSize = 14
    titleLabel.Font = Enum.Font.GothamBold
    titleLabel.TextTransparency = 0.3
    titleLabel.Parent = mainFrame
    
    local timeLabel = Instance.new("TextLabel")
    timeLabel.Name = "TimeLabel"
    timeLabel.Size = UDim2.new(1, 0, 0, 50)
    timeLabel.Position = UDim2.new(0, 0, 0, 35)
    timeLabel.BackgroundTransparency = 1
    timeLabel.Text = "12:00 AM"
    timeLabel.TextColor3 = Color3.fromRGB(255, 255, 255)
    timeLabel.TextSize = 36
    timeLabel.Font = Enum.Font.GothamBold
    timeLabel.Parent = mainFrame
    
    local dotsLabel = Instance.new("TextLabel")
    dotsLabel.Name = "DotsLabel"
    dotsLabel.Size = UDim2.new(0, 20, 0, 20)
    dotsLabel.Position = UDim2.new(1, -30, 0, 10)
    dotsLabel.BackgroundTransparency = 1
    dotsLabel.Text = "●"
    dotsLabel.TextColor3 = Color3.fromRGB(0, 255, 100)
    dotsLabel.TextSize = 16
    dotsLabel.Font = Enum.Font.GothamBold
    dotsLabel.Parent = mainFrame
    
    makeDraggable(mainFrame)
    
    spawn(function()
        while TimerGui and TimerGui.Parent do
            for i = 1, 20 do
                if stroke and stroke.Parent then
                    stroke.Transparency = 0.3 + (math.sin(i / 20 * math.pi * 2) * 0.2)
                end
                task.wait(0.05)
            end
        end
    end)
    
    spawn(function()
        local dotStates = {"●", "●●", "●●●"}
        local index = 1
        while TimerGui and TimerGui.Parent do
            if dotsLabel and dotsLabel.Parent then
                dotsLabel.Text = dotStates[index]
                index = (index % 3) + 1
            end
            task.wait(0.5)
        end
    end)
    
    return timeLabel
end

local function updateTimerDisplay()
    if not TimerGui or not TimerGui.Parent then return end
    
    local mainFrame = TimerGui:FindFirstChild("MainFrame")
    if not mainFrame then return end
    
    local timeLabel = mainFrame:FindFirstChild("TimeLabel")
    if not timeLabel then return end
    
    local stroke = mainFrame:FindFirstChild("UIStroke")
    
    local hour, minute = getGameTime()
    
    if hour and minute then
        local displayText = string.format("%d:%02d AM", hour, minute)
        timeLabel.Text = displayText
        
        if hour == 6 or (hour == 5 and minute >= 50) then
            timeLabel.TextColor3 = Color3.fromRGB(0, 255, 100)
            if stroke then stroke.Color = Color3.fromRGB(0, 255, 100) end
        elseif hour >= 4 then
            timeLabel.TextColor3 = Color3.fromRGB(255, 255, 100)
            if stroke then stroke.Color = Color3.fromRGB(255, 255, 0) end
        elseif hour >= 2 then
            timeLabel.TextColor3 = Color3.fromRGB(255, 150, 50)
            if stroke then stroke.Color = Color3.fromRGB(255, 100, 0) end
        else
            timeLabel.TextColor3 = Color3.fromRGB(255, 255, 255)
            if stroke then stroke.Color = Color3.fromRGB(100, 150, 255) end
        end
    else
        timeLabel.Text = "12:00 AM"
        timeLabel.TextColor3 = Color3.fromRGB(255, 255, 255)
    end
end

-- ==================== ESP FUNCTIONS ====================

local function createHighlight(model, color)
    local highlight = Instance.new("Highlight")
    highlight.FillColor = color
    highlight.OutlineColor = color
    highlight.FillTransparency = HighlightTransparency
    highlight.OutlineTransparency = 0
    highlight.Parent = model
    return highlight
end

local function createNameTag(model, name, color)
    local head = model:FindFirstChild("Head") or model:FindFirstChild("HumanoidRootPart") or model.PrimaryPart
    if not head then return nil end
    
    local billboard = Instance.new("BillboardGui")
    billboard.Name = "ESPNameTag"
    billboard.Adornee = head
    billboard.Size = UDim2.new(0, 100, 0, 40)
    billboard.StudsOffset = Vector3.new(0, 3, 0)
    billboard.AlwaysOnTop = true
    billboard.Parent = head
    
    local textLabel = Instance.new("TextLabel")
    textLabel.Size = UDim2.new(1, 0, 1, 0)
    textLabel.BackgroundTransparency = 1
    textLabel.Text = name
    textLabel.TextColor3 = color
    textLabel.TextStrokeTransparency = 0.5
    textLabel.TextSize = TextSize
    textLabel.Font = Enum.Font.SourceSansBold
    textLabel.Parent = billboard
    
    return billboard
end

local function getAnimatronicName(model)
    local modelName = model.Name:lower()
    
    if modelName:find("golden") then
        return "Golden Freddy"
    elseif modelName:find("freddy") then
        return "Freddy"
    elseif modelName:find("foxy") then
        return "Foxy"
    elseif modelName:find("bonnie") then
        return "Bonnie"
    elseif modelName:find("chica") then
        return "Chica"
    elseif modelName:find("puppet") then
        return "Puppet"
    elseif modelName:find("cupcake") then
        return "Cupcake"
    end
    
    return nil
end

local function addESP(model)
    if ESPObjects[model] then return end
    
    local animatronicName = getAnimatronicName(model)
    if not animatronicName then return end
    
    local color = AnimatronicColors[animatronicName]
    
    local highlight = createHighlight(model, color)
    local nameTag = createNameTag(model, animatronicName, color)
    
    ESPObjects[model] = {
        highlight = highlight,
        nameTag = nameTag
    }
end

local function removeESP(model)
    if ESPObjects[model] then
        if ESPObjects[model].highlight then
            ESPObjects[model].highlight:Destroy()
        end
        if ESPObjects[model].nameTag then
            ESPObjects[model].nameTag:Destroy()
        end
        ESPObjects[model] = nil
    end
end

local function clearAllESP()
    for model, _ in pairs(ESPObjects) do
        removeESP(model)
    end
end

local function scanWorkspace()
    for _, descendant in pairs(workspace:GetDescendants()) do
        if descendant:IsA("Model") and descendant:FindFirstChildOfClass("Humanoid") then
            if getAnimatronicName(descendant) then
                addESP(descendant)
            end
        end
    end
end

-- ==================== PLAYER FUNCTIONS ====================

local function applySpeed(character)
    if not SpeedEnabled then return end
    
    local humanoid = character:FindFirstChild("Humanoid")
    if humanoid then
        humanoid.WalkSpeed = CustomSpeed
    end
end

local function toggleThirdPerson(enabled)
    ThirdPersonEnabled = enabled
    if LocalPlayer.Character then
        local humanoid = LocalPlayer.Character:FindFirstChild("Humanoid")
        if humanoid then
            if enabled then
                humanoid.CameraOffset = Vector3.new(0, 2, 8)
            else
                humanoid.CameraOffset = Vector3.new(0, 0, 0)
            end
        end
    end
end

local function toggleFullbright(enabled)
    FullbrightEnabled = enabled
    
    if enabled then
        OriginalLightingSettings = {
            Ambient = Lighting.Ambient,
            Brightness = Lighting.Brightness,
            ColorShift_Bottom = Lighting.ColorShift_Bottom,
            ColorShift_Top = Lighting.ColorShift_Top,
            OutdoorAmbient = Lighting.OutdoorAmbient,
            FogEnd = Lighting.FogEnd,
            FogStart = Lighting.FogStart
        }
        
        Lighting.Ambient = Color3.fromRGB(255, 255, 255)
        Lighting.Brightness = 2
        Lighting.ColorShift_Bottom = Color3.fromRGB(255, 255, 255)
        Lighting.ColorShift_Top = Color3.fromRGB(255, 255, 255)
        Lighting.OutdoorAmbient = Color3.fromRGB(255, 255, 255)
        Lighting.FogEnd = 100000
        Lighting.FogStart = 0
    else
        for property, value in pairs(OriginalLightingSettings) do
            Lighting[property] = value
        end
    end
end

local function toggleNoclip(enabled)
    NoclipEnabled = enabled
    
    if NoclipConnection then
        NoclipConnection:Disconnect()
        NoclipConnection = nil
    end
    
    if enabled then
        NoclipConnection = RunService.Stepped:Connect(function()
            if LocalPlayer.Character then
                for _, part in pairs(LocalPlayer.Character:GetDescendants()) do
                    if part:IsA("BasePart") then
                        part.CanCollide = false
                    end
                end
            end
        end)
    else
        if LocalPlayer.Character then
            for _, part in pairs(LocalPlayer.Character:GetDescendants()) do
                if part:IsA("BasePart") and part.Name ~= "HumanoidRootPart" then
                    part.CanCollide = true
                end
            end
        end
    end
end

local function createTpTool()
    if TpTool then TpTool:Destroy() end
    
    TpTool = Instance.new("Tool")
    TpTool.Name = "TP Tool"
    TpTool.RequiresHandle = false
    TpTool.Parent = LocalPlayer.Backpack
    
    TpTool.Activated:Connect(function()
        local mouse = LocalPlayer:GetMouse()
        if mouse.Target and LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart") then
            local targetPosition = mouse.Hit.Position + Vector3.new(0, 3, 0)
            
            if AntiTpProtection then
                local hrp = LocalPlayer.Character.HumanoidRootPart
                local distance = (hrp.Position - targetPosition).Magnitude
                local steps = math.max(math.ceil(distance / 50), 3)
                
                for i = 1, steps do
                    local alpha = i / steps
                    hrp.CFrame = CFrame.new(hrp.Position:Lerp(targetPosition, alpha))
                    task.wait(0.03)
                end
            else
                LocalPlayer.Character.HumanoidRootPart.CFrame = CFrame.new(targetPosition)
            end
        end
    end)
end

local function teleportToTopOfMap()
    if not LocalPlayer.Character or not LocalPlayer.Character:FindFirstChild("HumanoidRootPart") then
        return
    end
    
    local hrp = LocalPlayer.Character.HumanoidRootPart
    local currentPos = hrp.Position
    local targetPos = Vector3.new(currentPos.X, currentPos.Y + 500, currentPos.Z)
    
    if AntiTpProtection then
        local steps = 20
        for i = 1, steps do
            local alpha = i / steps
            hrp.CFrame = CFrame.new(currentPos:Lerp(targetPos, alpha))
            task.wait(0.05)
        end
    else
        hrp.CFrame = CFrame.new(targetPos)
    end
end

local function toggleInstantPrompt(enabled)
    InstantPrompt = enabled
    
    if enabled then
        for _, descendant in pairs(workspace:GetDescendants()) do
            if descendant:IsA("ProximityPrompt") then
                descendant.HoldDuration = 0
            end
        end
    end
end

local function toggleNoJumpCooldown(enabled)
    NoJumpCooldown = enabled
    
    if LocalPlayer.Character then
        local humanoid = LocalPlayer.Character:FindFirstChild("Humanoid")
        if humanoid then
            if enabled then
                humanoid.UseJumpPower = true
                humanoid.JumpPower = 50
            end
        end
    end
end

-- ==================== CHARACTER SETUP ====================

local function onCharacterAdded(character)
    applySpeed(character)
    
    local humanoid = character:WaitForChild("Humanoid", 5)
    if humanoid then
        humanoid:GetPropertyChangedSignal("WalkSpeed"):Connect(function()
            if SpeedEnabled and humanoid.WalkSpeed ~= CustomSpeed then
                humanoid.WalkSpeed = CustomSpeed
            end
        end)
        
        if NoJumpCooldown then
            humanoid.UseJumpPower = true
            humanoid.JumpPower = 50
        end
    end
    
    if ThirdPersonEnabled then
        toggleThirdPerson(true)
    end
    
    if TpToolEnabled then
        task.wait(1)
        createTpTool()
    end
    
    if NoclipEnabled then
        toggleNoclip(true)
    end
    
    GameTimerValue = nil
end

if LocalPlayer.Character then
    onCharacterAdded(LocalPlayer.Character)
end

LocalPlayer.CharacterAdded:Connect(onCharacterAdded)

