-- ==================== WORKSPACE LISTENERS ====================

workspace.DescendantAdded:Connect(function(descendant)
    if ESPEnabled and descendant:IsA("Model") then
        task.wait(0.1)
        if descendant:FindFirstChildOfClass("Humanoid") and getAnimatronicName(descendant) then
            addESP(descendant)
        end
    end
    
    if InstantPrompt and descendant:IsA("ProximityPrompt") then
        descendant.HoldDuration = 0
    end
end)

workspace.DescendantRemoving:Connect(function(descendant)
    if descendant:IsA("Model") and ESPObjects[descendant] then
        removeESP(descendant)
    end
end)

-- ==================== RENDER LOOP ====================

RunService.RenderStepped:Connect(function()
    -- Update ESP
    if ESPEnabled then
        for model, espData in pairs(ESPObjects) do
            if model and model.Parent and espData.nameTag then
                local rootPart = model:FindFirstChild("HumanoidRootPart") or model.PrimaryPart
                if rootPart and LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart") then
                    local distance = (LocalPlayer.Character.HumanoidRootPart.Position - rootPart.Position).Magnitude
                    local animName = getAnimatronicName(model)
                    espData.nameTag.TextLabel.Text = string.format("%s [%.0fm]", animName, distance)
                end
            end
        end
    end
    
    -- Enforce speed
    if SpeedEnabled and LocalPlayer.Character then
        local humanoid = LocalPlayer.Character:FindFirstChild("Humanoid")
        if humanoid and humanoid.WalkSpeed ~= CustomSpeed then
            humanoid.WalkSpeed = CustomSpeed
        end
    end
    
    -- Keep fullbright active
    if FullbrightEnabled then
        Lighting.FogEnd = 100000
        Lighting.FogStart = 0
    end
    
    -- Update timer
    if ShowTimer then
        updateTimerDisplay()
    end
    
    -- No jump cooldown enforcement
    if NoJumpCooldown and LocalPlayer.Character then
        local humanoid = LocalPlayer.Character:FindFirstChild("Humanoid")
        if humanoid then
            humanoid.UseJumpPower = true
        end
    end
end)

-- Periodic search for game timer
spawn(function()
    while task.wait(5) do
        if not GameTimerValue or not GameTimerValue.Parent then
            GameTimerValue = findGameTimer()
        end
    end
end)

